function cashChart(list,b,options={}){
 const isReport=options.report===true,range=isReport?statsRange():{start:(month||today().slice(0,7))+'-01',end:billISO(new Date(Number((month||today()).slice(0,4)),Number((month||today()).slice(5,7)),0))};
 const span=Math.round((new Date(range.end+'T00:00:00')-new Date(range.start+'T00:00:00'))/86400000)+1,byMonth=span>62,buckets=[],cursor=new Date(range.start+'T00:00:00');
 while(billISO(cursor)<=range.end&&buckets.length<400){const key=billISO(cursor).slice(0,byMonth?7:10);buckets.push({key,expense:0,income:0});if(byMonth)cursor.setFullYear(cursor.getFullYear(),cursor.getMonth()+1,1);else cursor.setDate(cursor.getDate()+1);}
 const map=new Map(buckets.map(x=>[x.key,x]));for(const t of list){if(!counted(t))continue;const x=map.get(iso(t.date).slice(0,byMonth?7:10));if(x)x[income(t)?'income':'expense']+=Math.abs(localValue(t,b));}
 const showExpense=!isReport||reportExpense,showIncome=!isReport||reportIncome,max=Math.max(1,...buckets.flatMap(x=>[showExpense?x.expense:0,showIncome?x.income:0])),context=isReport?'reports':'overview',selectedKey=chartSelection[context],label=x=>byMonth?Number(x.key.slice(5,7))+'月':Number(x.key.slice(8,10))+'日';
 const legend=`<div class="desk-chart-legend">${isReport?`<button aria-pressed="${showExpense}" onclick="desk254Series('expense')"><i></i>支出</button><button aria-pressed="${showIncome}" onclick="desk254Series('income')"><i></i>收入</button>`:'<span><i></i>支出</span><span><i></i>收入</span>'}</div>`;
 const bubble=(x,i,line=false)=>selectedKey===x.key?`<span class="desk-chart-bubble255 ${i<3?'edge-start':i>buckets.length-4?'edge-end':''}" style="bottom:calc(${Math.max(showExpense?x.expense:0,showIncome?x.income:0)/max*(line?81:100)+(line?13:0)}% + 9px)" aria-hidden="true"><b>${e(x.key)}</b><em class="desk-expense">支出 ${e(amount(x.expense,b.currency))}</em><em class="desk-income">收入 ${e(amount(x.income,b.currency))}</em></span>`:'';
 let plot='';
 if(isReport&&reportStyle==='line'){
  const width=800,height=180,px=i=>buckets.length===1?width/2:i/(buckets.length-1)*width,py=n=>height-n/max*(height-12);
  plot=`<div class="desk-line254"><svg viewBox="0 0 ${width} ${height+28}" preserveAspectRatio="none" role="group" aria-label="收支折線圖">${[.25,.5,.75].map(v=>`<path d="M0 ${py(max*v)}H800" stroke="#e7edf7" stroke-dasharray="4 4"/>`).join('')}${[['expense',showExpense,'#6a98ef'],['income',showIncome,'#82bfae']].filter(x=>x[1]).map(([kind,_,color])=>`<polyline fill="none" stroke="${color}" stroke-width="2.5" points="${buckets.map((x,i)=>px(i)+','+py(x[kind])).join(' ')}"/>${buckets.map((x,i)=>`<g><circle cx="${px(i)}" cy="${py(x[kind])}" r="4" fill="${color}"/></g>`).join('')}`).join('')}</svg><div class="desk-line-targets254">${buckets.map((x,i)=>`<button aria-pressed="${selectedKey===x.key}" aria-label="查看 ${e(x.key)} 收支明細" onclick="desk254Chart('${context}','${x.key}')"><span class="desk-line-label255">${e(label(x))}</span>${bubble(x,i,true)}</button>`).join('')}</div></div>`;
 }else plot=`<div class="desk-bars" aria-label="${isReport?'期間':'每日'}收支棒形圖">${[1,2,3].map(i=>`<div class="desk-chart-line" style="bottom:${i*25}%"><span>${e(amount(max*i/4,b.currency))}</span></div>`).join('')}<div class="desk-bar-columns">${buckets.map((x,i)=>`<button class="desk-bar254 ${selectedKey===x.key?'selected':''}" aria-label="${e(x.key)} · 支出 ${e(amount(x.expense,b.currency))} · 收入 ${e(amount(x.income,b.currency))}，查看明細" aria-pressed="${selectedKey===x.key}" onclick="desk254Chart('${context}','${x.key}')"><span class="desk-bar-pair254">${showExpense?`<i style="height:${x.expense/max*100}%"></i>`:''}${showIncome?`<i class="desk-bar-income254" style="height:${x.income/max*100}%"></i>`:''}</span><small>${buckets.length<=12||i===0||(i+1)%5===0||i===buckets.length-1?e(label(x)):''}</small>${bubble(x,i)}</button>`).join('')}</div></div>`;
 const selectedBucket=buckets.find(x=>x.key===selectedKey);
 const summary=selectedBucket?`<div class="desk-chart-selection254" aria-label="已選日期的交易明細"><span>當${byMonth?'月':'日'}交易明細</span><button class="desk-link" onclick="desk254ChartClose('${context}')">收起明細 ×</button></div>${records254(list.filter(t=>iso(t.date).startsWith(selectedKey)),b)}`:`<p class="desk-chart-caption254">點擊${isReport&&reportStyle==='line'?'折線位置':'棒形圖'}，查看當${byMonth?'月':'日'}的交易明細。</p>`;
 return legend+plot+summary;
}
